122→/// Handle a menu item click by ID.
123→fn handle_menu_event(app: &AppHandle, id: &str) {
124→    use tauri_plugin_notification::NotificationExt;
125→    match id {
126→        "open" => {
127→            // Open ~/CipherBox in the platform file manager
128→            let mount_point = dirs::home_dir()
129→                .map(|h| h.join("CipherBox"))
130→                .unwrap_or_default();
131→            if !mount_point.exists() {
132→                log::warn!("Mount point {} does not exist — filesystem may not be mounted", mount_point.display());
133→                // Show notification instead of a confusing file manager error
134→                if let Err(e) = app.notification()
135→                    .builder()
136→                    .title("CipherBox")
137→                    .body("Vault is not mounted. Please sign in first.")
138→                    .show()
139→                {
140→                    log::error!("Failed to show notification: {}", e);
141→                }
142→                return;
143→            }
144→            #[cfg(target_os = "macos")]
145→            {
146→                if let Err(e) = std::process::Command::new("open")
147→                    .arg(mount_point.to_str().unwrap_or("~/CipherBox"))
148→                    .spawn()
149→                {
150→                    log::error!("Failed to open CipherBox in Finder: {}", e);
151→                }
152→            }
153→            #[cfg(target_os = "windows")]
154→            {
155→                if let Err(e) = std::process::Command::new("explorer.exe")
156→                    .arg(mount_point.to_str().unwrap_or_default())
157→                    .spawn()
158→                {
159→                    log::error!("Failed to open CipherBox in Explorer: {}", e);
160→                }
161→            }
162→        }
163→        "sync" => {
164→            // Trigger immediate sync via the SyncDaemon channel stored in AppState
165→            let state = app.state::<crate::state::AppState>();
166→            if let Some(tx) = state.sync_trigger.read().ok().and_then(|g| g.clone()) {
167→                let _ = tx.try_send(());
168→                log::info!("Manual sync triggered");
169→            } else {
170→                log::warn!("Sync trigger channel not available");
171→            }
172→        }
173→        "login" => {
174→            // Show existing window or create a new one with on_new_window
175→            // handler for OAuth popups.
176→            if let Some(window) = app.get_webview_window("main") {
177→                // Reload page to reset stale DOM & Web3Auth state after logout
178→                let _ = window.eval("location.reload()");
179→                let _ = window.show();
180→                let _ = window.set_focus();
181→            } else {
182→                log::info!("Creating login webview window");
183→                match tauri::WebviewWindowBuilder::new(
184→                    app,
185→                    "main",
186→                    tauri::WebviewUrl::App("index.html".into()),
187→                )
188→                .title("CipherBox")
189→                .inner_size(480.0, 600.0)
190→                .center()
191→                .resizable(false)
192→                .on_new_window({
193→                    let app_handle = app.clone();
194→                    move |url, features| {
195→                        // Create popup with shared WKWebViewConfiguration so
196→                        // window.opener is preserved for OAuth postMessage callbacks
197→                        let n = POPUP_COUNTER.fetch_add(1, Ordering::Relaxed);
198→                        let label = format!("oauth-popup-{}", n);
199→                        match tauri::WebviewWindowBuilder::new(
200→                            &app_handle,
201→                            &label,
202→                            tauri::WebviewUrl::External("about:blank".parse().unwrap()),
203→                        )
204→                        .window_features(features)
205→                        .title(url.as_str())
206→                        .inner_size(500.0, 700.0)
207→                        .center()
208→                        .build()
209→                        {
210→                            Ok(window) => tauri::webview::NewWindowResponse::Create { window },
211→                            Err(e) => {
212→                                log::error!("Failed to create OAuth popup: {}", e);
213→                                tauri::webview::NewWindowResponse::Deny
214→                            }
215→                        }
216→                    }
217→                })
218→                .build()
219→                {
220→                    Ok(window) => {
221→                        let _ = window.show();
222→                        let _ = window.set_focus();
223→                    }
224→                    Err(e) => {
225→                        log::error!("Failed to create login window: {}", e);
226→                    }
227→                }
228→            }
229→        }
230→        "logout" => {
231→            let app_handle = app.clone();
232→            tauri::async_runtime::spawn(async move {
233→                let state = app_handle.state::<crate::state::AppState>();
234→
235→                // Unmount filesystem (FUSE on macOS, WinFsp on Windows)
236→                #[cfg(any(feature = "fuse", feature = "winfsp"))]
237→                {
238→                    if let Err(e) = crate::fuse::unmount_filesystem() {
239→                        log::warn!("Filesystem unmount during logout failed: {}", e);
240→                    }
241→                    *state.mount_status.write().await = crate::state::MountStatus::Unmounted;
242→                }
243→
244→                // POST /auth/logout (best-effort)
245→                let _ = state.api.authenticated_post("/auth/logout", &()).await;
246→
247→                // Delete refresh token from Keychain
248→                if let Some(ref user_id) = *state.user_id.read().await {
249→                    let _ = crate::api::auth::delete_refresh_token(user_id);
250→                }
251→
252→                // Zero all sensitive keys
253→                state.clear_keys().await;
254→
255→                // Update tray status
256→                if let Err(e) = update_tray_status(&app_handle, &TrayStatus::NotConnected) {
257→                    log::warn!("Failed to update tray status after logout: {}", e);
258→                }
259→
260→                log::info!("Logout complete (via tray menu)");
261→            });
262→        }
263→        "quit" => {
264→            // Unmount filesystem if mounted, then exit
265→            #[cfg(any(feature = "fuse", feature = "winfsp"))]
266→            {
267→                let _ = crate::fuse::unmount_filesystem();
268→            }
269→            app.exit(0);
270→        }
271→        _ => {
272→            log::debug!("Unknown tray menu event: {}", id);
273→        }
274→    }
275→}
