  1→//! Encrypted device registry client.
  2→//!
  3→//! Manages registration of the desktop device in the ECIES-encrypted
  4→//! device registry stored on IPFS/IPNS. The registry enables cross-device
  5→//! awareness: the web app can see the desktop as a known device, and the
  6→//! desktop can participate in device approval flows.
  7→//!
  8→//! IMPORTANT: Registry operations must NEVER block login.
  9→//! All errors are caught and logged by the caller (tokio::spawn wrapper).
 10→
 11→pub mod types;
 12→
 13→use std::sync::Arc;
 14→
 15→use base64::Engine;
 16→
 17→use crate::api::client::ApiClient;
 18→use crate::api::ipns::IpnsPublishRequest;
 19→use crate::crypto;
 20→use types::{DeviceAuthStatus, DeviceEntry, DevicePlatform, DeviceRegistry};
 21→
 22→/// Register this desktop device in the encrypted device registry.
 23→///
 24→/// Steps:
 25→/// 1. Derive registry IPNS keypair via HKDF
 26→/// 2. Try to resolve existing registry from IPNS
 27→/// 3. Build device entry for this desktop
 28→/// 4. Update or create registry with the device entry
 29→/// 5. Encrypt registry with user's public key (ECIES)
 30→/// 6. Upload to IPFS and publish IPNS record
 31→///
 32→/// This function should be called via `tokio::spawn` so failures never block login.
 33→pub async fn register_device(
 34→    api: &Arc<ApiClient>,
 35→    private_key: &[u8; 32],
 36→    public_key: &[u8],
 37→    _user_id: &str,
 38→) -> Result<(), String> {
 39→    // 1. Derive registry IPNS keypair via HKDF
 40→    let (reg_ipns_priv, _reg_ipns_pub, reg_ipns_name) =
 41→        crypto::hkdf::derive_registry_ipns_keypair(private_key)
 42→            .map_err(|e| format!("Registry IPNS derivation failed: {}", e))?;
 43→
 44→    // 2. Try to resolve existing registry from IPNS
 45→    let existing_registry = match fetch_and_decrypt_registry(api, &reg_ipns_name, private_key).await
 46→    {
 47→        Ok(reg) => Some(reg),
 48→        Err(_) => None, // No registry exists yet (first device)
 49→    };
 50→
 51→    // 3. Build device entry for this desktop
 52→    let device_id = get_or_create_device_id();
 53→    let device_entry = DeviceEntry {
 54→        device_id: device_id.clone(),
 55→        public_key: hex::encode(public_key),
 56→        name: get_device_name(),
 57→        platform: DevicePlatform::Macos,
 58→        app_version: env!("CARGO_PKG_VERSION").to_string(),
 59→        device_model: get_device_model(),
 60→        ip_hash: String::new(), // Not tracked for desktop
 61→        status: if existing_registry.is_none() {
 62→            DeviceAuthStatus::Authorized // First device auto-authorized
 63→        } else {
 64→            DeviceAuthStatus::Pending
 65→        },
 66→        created_at: now_ms(),
 67→        last_seen_at: now_ms(),
 68→        revoked_at: None,
 69→        revoked_by: None,
 70→    };
 71→
 72→    // 4. Build updated registry
 73→    let mut registry = existing_registry.unwrap_or(DeviceRegistry {
 74→        version: "v1".to_string(),
 75→        sequence_number: 0,
 76→        devices: vec![],
 77→    });
 78→
 79→    // Update existing device entry or add new one
 80→    if let Some(existing) = registry
 81→        .devices
 82→        .iter_mut()
 83→        .find(|d| d.device_id == device_id)
 84→    {
 85→        existing.last_seen_at = now_ms();
 86→        existing.app_version = env!("CARGO_PKG_VERSION").to_string();
 87→    } else {
 88→        registry.devices.push(device_entry);
 89→    }
 90→    registry.sequence_number += 1;
 91→
 92→    // 5. Encrypt registry with user's public key (ECIES)
 93→    let registry_json = serde_json::to_vec(&registry)
 94→        .map_err(|e| format!("Registry serialization failed: {}", e))?;
 95→    let encrypted = crypto::ecies::wrap_key(&registry_json, public_key)
 96→        .map_err(|e| format!("Registry encryption failed: {}", e))?;
 97→
 98→    // 6. Upload encrypted registry to IPFS
 99→    let cid = crate::api::ipfs::upload_content(api, &encrypted).await?;
100→
101→    // 7. Create and publish IPNS record
102→    let reg_ipns_priv_arr: [u8; 32] = reg_ipns_priv.as_slice()
103→        .try_into()
104→        .map_err(|_| "Invalid registry IPNS key length".to_string())?;
105→    let value = format!("/ipfs/{}", cid);
106→    let record =
107→        crypto::ipns::create_ipns_record(&reg_ipns_priv_arr, &value, registry.sequence_number, 86_400_000)
108→            .map_err(|e| format!("IPNS record creation failed: {}", e))?;
109→    let marshaled = crypto::ipns::marshal_ipns_record(&record)
110→        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
111→    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
112→
113→    let publish_req = IpnsPublishRequest {
114→        ipns_name: reg_ipns_name,
115→        record: record_base64,
116→        metadata_cid: cid,
117→        encrypted_ipns_private_key: None,
118→        key_epoch: None,
119→    };
120→    crate::api::ipns::publish_ipns(api, &publish_req).await?;
121→
122→    log::info!(
123→        "Device registered in encrypted registry (device_id: {})",
124→        device_id
125→    );
126→    Ok(())
127→}
