129→/// Fetch and decrypt existing registry from IPNS.
130→async fn fetch_and_decrypt_registry(
131→    api: &ApiClient,
132→    ipns_name: &str,
133→    private_key: &[u8; 32],
134→) -> Result<DeviceRegistry, String> {
135→    let resolve = crate::api::ipns::resolve_ipns(api, ipns_name).await?;
136→    let encrypted = crate::api::ipfs::fetch_content(api, &resolve.cid).await?;
137→    let decrypted = crypto::ecies::unwrap_key(&encrypted, private_key)
138→        .map_err(|e| format!("Registry decryption failed: {}", e))?;
139→    serde_json::from_slice(&decrypted).map_err(|e| format!("Registry parse failed: {}", e))
140→}
