155→/// Get or create a persistent device ID stored in macOS Keychain.
156→///
157→/// Uses the `keyring` crate with service "cipherbox-desktop" and key "device-id".
158→/// If no device ID exists, generates a UUID v4 and stores it.
159→///
160→/// In debug builds, skips Keychain entirely and uses an ephemeral UUID.
161→/// This avoids macOS Keychain permission prompts that fire on every rebuild
162→/// (each build produces a new binary signature).
163→fn get_or_create_device_id() -> String {
164→    #[cfg(debug_assertions)]
165→    {
166→        log::info!("Debug mode: using ephemeral device ID (no Keychain access)");
167→        return generate_uuid_v4();
168→    }
169→
170→    #[cfg(not(debug_assertions))]
171→    {
172→        let entry = match keyring::Entry::new("cipherbox-desktop", "device-id") {
173→            Ok(e) => e,
174→            Err(e) => {
175→                log::warn!("Keychain entry creation failed: {}. Using ephemeral ID.", e);
176→                return generate_uuid_v4();
177→            }
178→        };
179→
180→        match entry.get_password() {
181→            Ok(id) if !id.is_empty() => id,
182→            _ => {
183→                let uuid = generate_uuid_v4();
184→
185→                let _ = entry.delete_credential();
186→                if let Err(e) = entry.set_password(&uuid) {
187→                    log::warn!(
188→                        "Failed to store device ID in Keychain: {}. Using ephemeral ID.",
189→                        e
190→                    );
191→                }
192→                uuid
193→            }
194→        }
195→    }
196→}
